  'Attach a photo or file': { es: 'Adjuntar una foto o archivo', fr: 'Joindre une photo ou un fichier', pt: 'Anexar uma foto ou arquivo', de: 'Foto oder Datei anhängen', ja: '写真またはファイルを添付', zh: '附加照片或文件', ar: 'إرفاق صورة أو ملف', hi: 'फ़ोटो या फ़ाइल संलग्न करें', it: 'Allega una foto o un file', ru: 'Прикрепить фото или файл', ko: '사진 또는 파일 첨부' },
