  'Annual, save 30%': { es: 'Anual, ahorra 30%', fr: 'Annuel, économisez 30 %', pt: 'Anual, economize 30%', de: 'Jährlich, spare 30 %', ja: '年払い、30%お得', zh: '按年，节省30%', ar: 'سنويًا، وفّر 30٪', hi: 'वार्षिक, 30% बचाएं', it: 'Annuale, risparmia il 30%', ru: 'Годовой, экономия 30%', ko: '연간, 30% 할인' },
