  'billed monthly': { es: 'facturado mensualmente', fr: 'facturé mensuellement', pt: 'cobrado mensalmente', de: 'monatlich abgerechnet', ja: '月払い請求', zh: '按月计费', ar: 'يُفوتر شهريًا', hi: 'मासिक रूप से बिल किया गया', it: 'fatturato mensilmente', ru: 'оплата ежемесячно', ko: '월간 청구' },
