  'Password, ads, billing': { es: 'Contraseña, anuncios, facturación', fr: 'Mot de passe, publicités, facturation', pt: 'Senha, anúncios, faturamento', de: 'Passwort, Anzeigen, Abrechnung', ja: 'パスワード、広告、請求', zh: '密码、广告、账单', ar: 'كلمة المرور، الإعلانات، الفوترة', hi: 'पासवर्ड, विज्ञापन, बिलिंग', it: 'Password, annunci, fatturazione', ru: 'Пароль, реклама, оплата', ko: '비밀번호, 광고, 결제' },
  "Pictures you've hidden from your profile": { es: 'Fotos que has ocultado de tu perfil', fr: 'Photos que vous avez masquées de votre profil', pt: 'Fotos que você ocultou do seu perfil', de: 'Bilder, die du aus deinem Profil ausgeblendet hast', ja: 'プロフィールから非表示にした写真', zh: '您从个人资料中隐藏的照片', ar: 'الصور التي أخفيتها عن ملفك الشخصي', hi: 'वे तस्वीरें जिन्हें आपने अपनी प्रोफ़ाइल से छिपाया है', it: 'Foto che hai nascosto dal tuo profilo', ru: 'Фото, скрытые из вашего профиля', ko: '프로필에서 숨긴 사진' },
  'Control who can view your profile': { es: 'Controla quién puede ver tu perfil', fr: 'Contrôlez qui peut voir votre profil', pt: 'Controle quem pode ver seu perfil', de: 'Steuere, wer dein Profil sehen kann', ja: 'プロフィールを閲覧できる人を管理', zh: '控制谁可以查看您的资料', ar: 'تحكم في من يمكنه رؤية ملفك الشخصي', hi: 'नियंत्रित करें कि आपकी प्रोफ़ाइल कौन देख सकता है', it: 'Controlla chi può vedere il tuo profilo', ru: 'Управляйте тем, кто может видеть ваш профиль', ko: '프로필을 볼 수 있는 사람 관리' },
  "People you've blocked or reported": { es: 'Personas que has bloqueado o denunciado', fr: 'Personnes que vous avez bloquées ou signalées', pt: 'Pessoas que você bloqueou ou denunciou', de: 'Personen, die du blockiert oder gemeldet hast', ja: 'ブロックまたは報告した人', zh: '您已屏蔽或举报的人', ar: 'الأشخاص الذين حظرتهم أو أبلغت عنهم', hi: 'वे लोग जिन्हें आपने ब्लॉक या रिपोर्ट किया है', it: 'Persone che hai bloccato o segnalato', ru: 'Люди, которых вы заблокировали или на которых пожаловались', ko: '차단하거나 신고한 사람' },
